+import java.io.File;
+import lombok.DirectoryRunner;
+import lombok.RunTestsViaDelombok;
+import lombok.transform.TestWithDelombok;
+
+public class FieldDefaultsRegression {
+    public static void main(String[] args) throws Throwable {
+        TestWithDelombok params = new TestWithDelombok();
+        for (String name : args) {
+            DirectoryRunner.FileTester tester = new RunTestsViaDelombok().createTester(
+                params, new File(params.getBeforeDirectory(), name), "javac", params.getVersion());
+            tester.runTest();
+            System.out.println("PASS " + name);
+        }
+    }
+}
